import math
from typing import List

import rclpy
from rclpy.node import Node
from rclpy.time import Time
from rclpy.qos import QoSProfile, QoSDurabilityPolicy, QoSReliabilityPolicy

from sensor_msgs.msg import LaserScan
from nav_msgs.msg import OccupancyGrid, Odometry
from visualization_msgs.msg import Marker, MarkerArray


class BubbleMemoryNode(Node):
    def __init__(self):
        super().__init__('bubble_memory')

        # params
        self.declare_parameter('scan_topic', '/scan')
        self.declare_parameter('map_topic', '/map')
        self.declare_parameter('odom_topic', '/ego_racecar/odom')
        self.declare_parameter('roi_deg', 70.0)
        self.declare_parameter('max_dist', 10.0)
        self.declare_parameter('margin', 0.30)
        self.declare_parameter('bubble_radius', 0.35)
        self.declare_parameter('decay_rate', 0.90)
        self.declare_parameter('add_value', 0.7)
        self.declare_parameter('publish_rate_hz', 15.0)
        self.declare_parameter('occ_threshold', 0.25)

        self.scan_topic = self.get_parameter('scan_topic').value
        self.map_topic  = self.get_parameter('map_topic').value
        self.odom_topic = self.get_parameter('odom_topic').value
        self.roi_rad    = math.radians(float(self.get_parameter('roi_deg').value))
        self.max_dist   = float(self.get_parameter('max_dist').value)
        self.margin     = float(self.get_parameter('margin').value)
        self.bubble_r   = float(self.get_parameter('bubble_radius').value)
        self.decay      = float(self.get_parameter('decay_rate').value)
        self.add_val    = float(self.get_parameter('add_value').value)
        self.pub_hz     = float(self.get_parameter('publish_rate_hz').value)
        self.occ_th     = float(self.get_parameter('occ_threshold').value)

        # state
        self.map: OccupancyGrid = None
        self.pose = (0.0, 0.0, 0.0)  # world pose
        self.grid_float = None       # same size as map, float [0..1]
        self.last_pub_time = Time(
            seconds=0, nanoseconds=0, clock_type=self.get_clock().clock_type
        )

        # pubs/subs
        map_qos = QoSProfile(
            depth=1,
            durability=QoSDurabilityPolicy.TRANSIENT_LOCAL,  # 래치된 과거 맵 수신
            reliability=QoSReliabilityPolicy.RELIABLE
        )
        self.sub_map = self.create_subscription(
            OccupancyGrid, self.map_topic, self.on_map, map_qos
        )
        self.sub_odom = self.create_subscription(Odometry, self.odom_topic, self.on_odom, 20)
        self.sub_scan = self.create_subscription(LaserScan, self.scan_topic, self.on_scan, 10)

        self.pub_grid   = self.create_publisher(OccupancyGrid, '/bubble_grid', 1)
        self.pub_marker = self.create_publisher(MarkerArray, '/bubble_markers', 1)

        self.get_logger().info('bubble_memory node up.')

    # --- callbacks ---
    def on_map(self, msg: OccupancyGrid):
        self.map = msg
        w = msg.info.width
        h = msg.info.height
        self.grid_float = [0.0] * (w * h)
        self.get_logger().info(f'map received: {w}x{h}, res={msg.info.resolution:.3f}')

    def on_odom(self, msg: Odometry):
        x = msg.pose.pose.position.x
        y = msg.pose.pose.position.y
        q = msg.pose.pose.orientation
        siny_cosp = 2.0 * (q.w * q.z + q.x * q.y)
        cosy_cosp = 1.0 - 2.0 * (q.y * q.y + q.z * q.z)
        yaw = math.atan2(siny_cosp, cosy_cosp)
        self.pose = (x, y, yaw)

    def on_scan(self, scan: LaserScan):
        if self.map is None or self.grid_float is None:
            return

        px, py, psi = self.pose

        # decay
        self._apply_decay()

        # ROI indices
        ang0 = scan.angle_min
        inc  = scan.angle_increment
        n    = len(scan.ranges)
        roi_min = -self.roi_rad
        roi_max = +self.roi_rad
        i0 = max(0, int(math.ceil((roi_min - ang0)/inc)))
        i1 = min(n-1, int(math.floor((roi_max - ang0)/inc)))

        # compare measured vs expected (raycast)
        angles = [ang0 + i*inc for i in range(n)]
        for i in range(i0, i1+1):
            rm = scan.ranges[i]
            if math.isinf(rm) or rm > min(self.max_dist, scan.range_max):
                continue

            th_local = angles[i]
            th_world = psi + th_local
            r_exp = self._raycast(px, py, th_world, min(self.max_dist, scan.range_max))

            # dynamic-like: measured closer than map-hit by margin
            if rm < (r_exp - self.margin):
                wx = px + rm * math.cos(th_world)
                wy = py + rm * math.sin(th_world)
                self._paint_bubble(wx, wy, self.bubble_r, self.add_val)

        # publish at fixed rate
        now = self.get_clock().now()
        if (now - self.last_pub_time).nanoseconds > (1e9 / max(1.0, self.pub_hz)):
            self._publish_grid()
            self._publish_markers()
            self.last_pub_time = now

    # --- helpers ---
    def _apply_decay(self):
        if self.grid_float is None:
            return
        df = self.grid_float
        for i in range(len(df)):
            v = df[i] * self.decay
            df[i] = v if v > 1e-4 else 0.0

    def _raycast(self, wx: float, wy: float, th: float, max_r: float) -> float:
        info = self.map.info
        res  = info.resolution
        cos_t, sin_t = math.cos(th), math.sin(th)

        def world_to_map(xw, yw):
            mx = int((xw - info.origin.position.x) / res)
            my = int((yw - info.origin.position.y) / res)
            return mx, my

        step = res * 0.5
        r = 0.0
        w = info.width
        h = info.height
        data = self.map.data

        while r < max_r:
            x = wx + r*cos_t
            y = wy + r*sin_t
            mx, my = world_to_map(x, y)
            if mx < 0 or my < 0 or mx >= w or my >= h:
                return r  # out of map
            occ = data[my * w + mx]
            if occ >= 50:
                return r
            r += step
        return max_r

    def _paint_bubble(self, wx: float, wy: float, radius: float, add_val: float):
        info = self.map.info
        res  = info.resolution
        w    = info.width
        h    = info.height

        # world -> map
        cx = int((wx - info.origin.position.x) / res)
        cy = int((wy - info.origin.position.y) / res)
        r_cells = max(1, int(radius / res))

        for dy in range(-r_cells, r_cells+1):
            for dx in range(-r_cells, r_cells+1):
                mx = cx + dx
                my = cy + dy
                if mx < 0 or my < 0 or mx >= w or my >= h:
                    continue
                if dx*dx + dy*dy <= r_cells*r_cells:
                    idx = my * w + mx
                    v = self.grid_float[idx] + add_val
                    self.grid_float[idx] = 1.0 if v > 1.0 else v

    def _publish_grid(self):
        info = self.map.info
        out = OccupancyGrid()
        out.header.frame_id = 'map'
        out.header.stamp = self.get_clock().now().to_msg()
        out.info = info

        occ = []
        thr = self.occ_th
        for v in self.grid_float:
            if v >= thr:
                occ.append(min(100, int(100 * v)))
            else:
                occ.append(0)
        out.data = occ
        self.pub_grid.publish(out)

    def _publish_markers(self):
        info = self.map.info
        res  = info.resolution
        w    = info.width
        h    = info.height
        orgx = info.origin.position.x
        orgy = info.origin.position.y
        df   = self.grid_float

        arr = MarkerArray()
        m0 = Marker()
        m0.action = Marker.DELETEALL
        arr.markers.append(m0)

        stride = max(1, int(self.bubble_r / max(1e-6, res)))
        kid = 0
        now = self.get_clock().now().to_msg()

        for my in range(0, h, stride):
            base = my * w
            for mx in range(0, w, stride):
                v = df[base + mx]
                if v < self.occ_th:
                    continue
                m = Marker()
                m.header.frame_id = 'map'
                m.header.stamp = now
                m.ns = 'bubble'
                m.id = kid; kid += 1
                m.type = Marker.CUBE
                m.action = Marker.ADD
                m.scale.x = m.scale.y = m.scale.z = res
                m.pose.position.x = orgx + (mx + 0.5) * res
                m.pose.position.y = orgy + (my + 0.5) * res
                m.pose.position.z = 0.0
                m.color.r = 1.0; m.color.g = 0.2; m.color.b = 0.2; m.color.a = max(0.2, min(0.9, v))
                arr.markers.append(m)

        self.pub_marker.publish(arr)


def main():
    rclpy.init()
    node = BubbleMemoryNode()
    rclpy.spin(node)
    node.destroy_node()
    rclpy.shutdown()
